      var trLine = new THREE.Line(trGeo, new THREE.LineBasicMaterial({ color: contrast ? 0xffffff : 0xf1e2c4, transparent: true, opacity: 0.55 - trI * 0.16 }));
      trLine.frustumCulled = false; trLine.visible = false;
